add_filter( 'woocommerce_checkout_fields', 'perfectpixel_free_checkout_minimal_fields', 9999 );

function perfectpixel_free_checkout_minimal_fields( $fields ) {
	if ( ! function_exists( 'WC' ) || ! WC()->cart || WC()->cart->needs_payment() ) {
		return $fields;
	}

	// Billing fields to keep when nothing has to be paid.
	$keep = array( 'billing_first_name', 'billing_email' );

	$fields['billing'] = array_intersect_key( $fields['billing'], array_flip( $keep ) );

	foreach ( $fields['billing'] as $key => $field ) {
		$fields['billing'][ $key ]['class'] = array( 'form-row-wide' );
	}

	return $fields;
}
